class FakeChannel:
    site: Site
    _reactor: object
    result: Dict[str, Any] = attr.Factory(dict)
    _producer: object = None

    @property
    def json_body(self):
        if not self.result:
            raise RuntimeError('Result is empty')
        body = self.result.get('body', b'')
        return json.loads(body.decode('utf-8'))

    @property
    def code(self):
        if not self.result:
            raise RuntimeError('Result is empty')
        return int(self.result.get('code', 0))

    @property
    def headers(self):
        if not self.result:
            raise RuntimeError('Result is empty')
        return Headers(self.result.get('headers', {}))

    def writeHeaders(self, version: str, code: int, reason: str, headers: Dict[bytes, Any]) -> None:
        self.result['version'] = version
        self.result['code'] = code
        self.result['reason'] = reason
        self.result['headers'] = headers

    def write(self, content: Union[bytes, bytearray, memoryview]) -> None:
        if not isinstance(content, (bytes, bytearray, memoryview)):
            raise TypeError('Content must be bytes-like')
        data = bytes(content)
        self.result.setdefault('body', b'')
        self.result['body'] += data

    def registerProducer(self, producer, streaming: bool) -> None:
        self._producer = producer
        if not streaming:
            try:
                producer.resumeProducing()
            except Exception:
                pass

    def unregisterProducer(self) -> None:
        self._producer = None

    def requestDone(self, _self) -> None:
