def _validate_ascii_token(token: str) -> bytes:
    if not isinstance(token, str):
        raise TypeError('Token must be a string')
    for ch in token:
        if ord(ch) < 32 or ord(ch) > 126 or ch.isspace():
            raise ValueError('Invalid character in token')
    token_bytes = token.encode('ascii')
    _validate_header_value(token_bytes)
    return token_bytes

def _validate_header_value(value: bytes) -> None:
    if b'\r' in value or b'\n' in value:
        raise ValueError('Header value contains CR or LF')

def _validate_http_method(method: Union[str, bytes]) -> bytes:
    """Validate that the HTTP method is a safe ASCII token."""
    if isinstance(method, str):
        method_bytes = method.encode('ascii')
    elif isinstance(method, bytes):
        method_bytes = method
    else:
        raise TypeError('Method must be str or bytes')
    token_str = method_bytes.decode('ascii')
    _validate_ascii_token(token_str)
    allowed = {b'GET', b'POST', b'PUT', b'DELETE', b'PATCH', b'HEAD', b'OPTIONS'}
    if method_bytes.upper() not in allowed:
        raise ValueError(f'Unsupported HTTP method: {method_bytes!r}')
    return method_bytes.upper()

def _validate_path_bytes(path_bytes: bytes) -> bytes:
    """Ensure the request path does not contain CR/LF or control characters."""
    if b'\r' in path_bytes or b'\n' in path_bytes:
        raise ValueError('Path contains CR or LF')
    for ch in path_bytes:
        if ch < 32 or ch > 126:
            raise ValueError('Path contains non-ASCII characters')
    return path_bytes

def make_request(
    reactor,
    method: Union[str, bytes],
    path: Union[str, bytes],
    content: Union[Dict[str, Any], str, bytes, bytearray, memoryview] = b'',
    access_token: Union[str, None] = None,
    request: type = Request,
    shorthand: bool = True,
    federation_auth_origin: Union[str, bytes, None] = None,
) -> Tuple[Request, FakeChannel]:
    method_bytes = _validate_http_method(method)

    if isinstance(path, str):
        path_bytes = path.encode('ascii')
    elif isinstance(path, bytes):
        path_bytes = path
    else:
        raise TypeError('Path must be str or bytes')
    path_bytes = _validate_path_bytes(path_bytes)

    if shorthand and not path_bytes.startswith(b'/_matrix'):
        path_bytes = b'/_matrix/identity/v2/' + path_bytes.lstrip(b'/')
        while b'//' in path_bytes:
            path_bytes = path_bytes.replace(b'//', b'/')
        path_bytes = _validate_path_bytes(path_bytes)

    if isinstance(content, dict):
        body_bytes = json.dumps(content, ensure_ascii=False).encode('utf-8')
    elif isinstance(content, text_type):
        body_bytes = content.encode('utf-8')
    elif isinstance(content, (bytes, bytearray, memoryview)):
        body_bytes = bytes(content)
    else:
        raise TypeError('Invalid content type')

    site = FakeSite()
    channel = FakeChannel(site=site, _reactor=reactor)
    req = request(channel)
    req.process = lambda: b''
    req.content = BytesIO(body_bytes)

    segments = [seg for seg in path_bytes.split(b'/') if seg]
    unquoted = []
    for seg in segments:
        u = unquote(seg)
        if u == b'..':
            raise ValueError('Path segment ".." is not allowed')
        unquoted.append(u)
    req.postpath = unquoted
    req.requestHeaders = Headers()

    if access_token is not None:
        if not isinstance(access_token, str):
            raise TypeError('Access token must be a string')
        token_bytes = _validate_ascii_token(access_token)
        req.requestHeaders.addRawHeader(b'Authorization', b'Bearer ' + token_bytes)

    if federation_auth_origin is not None:
        if isinstance(federation_auth_origin, str):
            origin_bytes = federation_auth_origin.encode('utf-8')
        elif isinstance(federation_auth_origin, bytes):
            origin_bytes = federation_auth_origin
        else:
            raise TypeError('Federation auth origin must be str or bytes')
        _validate_header_value(origin_bytes)
        value = b'X-Matrix origin=' + origin_bytes + b',key=,sig='
        req.requestHeaders.addRawHeader(b'Authorization', value)

    if body_bytes:
        req.requestHeaders.addRawHeader(b'Content-Type', b'application/json')

    req.requestReceived(method_bytes, path_bytes, b'1.1')
    return req, channel

class ToTwistedHandler(logging.Handler):
    tx_log = twisted.logger.Logger()

    def emit(self, record: logging.LogRecord) -> None:
        try:
            msg = self.format(record)
            level = record.levelname.lower()
            if level == 'warning':
                level = 'warn'
            try:
                log_level = twisted.logger.LogLevel.levelWithName(level)
            except Exception:
                log_level = twisted.logger.LogLevel.info
            self.tx_log.emit(message=msg, logLevel=log_level)
        except Exception:
            self.handleError(record)

def setup_logging() -> None:
    root = logging.getLogger()
    fmt = '%(asctime)s - %(name)s - %(lineno)d - %(levelname)s - %(message)s'
    handler = ToTwistedHandler()
    handler.setFormatter(logging.Formatter(fmt))
    if not any(isinstance(h, ToTwistedHandler) for h in root.handlers):
        root.addHandler(handler)
    level_str = os.getenv('SYDENT_TEST_LOG_LEVEL', 'ERROR').upper()
    level = getattr(logging, level_str, None)
    if not isinstance(level, int):
        level = logging.ERROR
    root.setLevel(level)

setup_logging()
